public class Cutting{

    public static int[] convertStringToIntArray(String s){
        String[] parts = s.trim().split("\\s+");
        int[] result = new int[parts.length];
        for(int i=0; i<parts.length; i++){
            result[i] = Integer.parseInt(parts[i]);
        }
        return result;
    }

    boolean isBalancedSubArray(int[] array, int index){
        int evenCount = 0, oddCount = 0;
        for(int i=0; i<=index; i++){
            if(array[i] % 2 == 0) evenCount++;
            else oddCount++;
        }
        return evenCount == oddCount;
    }

    int findOptimalCutIndex(int[] array, int coinsRemaining, Map<Integer,Boolean> usedCuts){
        int bestIndex = -1;
        int bestCost = coinsRemaining + 1;
        for(int i=1; i<array.length - 1; i++){
