#include <bits/stdc++.h>
using namespace std;

vector<int> convertStringToIntArray(const string& s) {
    vector<int> result;
    stringstream ss(s);
    int num;
    while (ss >> num) {
        result.push_back(num);
    }
    return result;
}

class Cutting {
public:
    bool isBalancedSubArray(const vector<int>& array, int index) {
        int evenCount = 0, oddCount = 0;
        for (int i = 0; i <= index; i++) {
            if (array[i] % 2 == 0) evenCount++;
            else oddCount++;
        }
        return evenCount == oddCount;
    }

    int findOptimalCutIndex(const vector<int>& array, int coinsRemaining, unordered_set<int>& usedCuts) {
        int bestIndex = -1;
        int bestCost = coinsRemaining + 1;
        for (int i = 1; i < (int)array.size() - 1; i++) {
            int cost = abs(array[i] - array[i + 1]);
            if (cost < bestCost && isBalancedSubArray(array, i) && usedCuts.find(i) == usedCuts.end()) {
                bestCost = cost;
                bestIndex = i;
            }
        }
        return bestIndex;
    }

    int computeMaxCuts(int n, int b, const vector<int>& a) {
        int coinsLeft = b;
        int totalCuts = 0;
        unordered_set<int> usedIndices;
        while (coinsLeft > 0) {
            int index = findOptimalCutIndex(a, coinsLeft, usedIndices);
            if (index >= 0) {
                usedIndices.insert(index);
                int cost = abs(a[index] - a[index + 1]);
                coinsLeft -= cost;
                totalCuts++;
            } else {
                break;
            }
        }
        return totalCuts;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line1, line2;
    getline(cin, line1);
    getline(cin, line2);
    vector<int> nB = convertStringToIntArray(line1);
    vector<int> a = convertStringToIntArray(line2);
    int n = nB[0];
    int b = nB[1];
    Cutting c;
    cout << c.computeMaxCuts(n, b, a) << "\n";
    return 0;
}

